package com.termux.app.voicepatrol;

import static org.junit.Assert.*;
import org.junit.Test;

public class LiveVoiceHandshakeTest {
 @Test public void timeoutConstantIsFifteenSeconds() { assertEquals(15000L,LiveVoiceHandshake.GATHERING_TIMEOUT_MILLIS); }
 @Test public void localDescriptionThenGatheringSendsOfferOnce() { LiveVoiceHandshake h=new LiveVoiceHandshake(); assertEquals(HandshakeStepKind.NONE,h.onLocalDescriptionSet().getKind()); assertEquals(HandshakeStepKind.SEND_OFFER,h.onIceGatheringComplete().getKind()); assertEquals(HandshakeStepKind.NONE,h.onIceGatheringComplete().getKind()); }
 @Test public void gatheringThenLocalDescriptionSendsOfferOnce() { LiveVoiceHandshake h=new LiveVoiceHandshake(); assertEquals(HandshakeStepKind.NONE,h.onIceGatheringComplete().getKind()); assertEquals(HandshakeStepKind.SEND_OFFER,h.onLocalDescriptionSet().getKind()); }
 @Test public void timeoutFailsWithoutOfferAndIsTerminal() { LiveVoiceHandshake h=new LiveVoiceHandshake(); HandshakeStep step=h.onGatheringTimedOut(); assertEquals(HandshakeStepKind.FAIL,step.getKind()); assertEquals("ice_gathering_timeout",step.getReason()); assertEquals(HandshakeStepKind.NONE,h.onGatheringTimedOut().getKind()); assertEquals(HandshakeStepKind.NONE,h.onLocalDescriptionSet().getKind()); }
 @Test public void timeoutAfterOfferProducesNoStep() { LiveVoiceHandshake h=new LiveVoiceHandshake(); h.onLocalDescriptionSet(); h.onIceGatheringComplete(); assertEquals(HandshakeStepKind.NONE,h.onGatheringTimedOut().getKind()); }
 @Test public void answerCarriesSdpForApplication() { LiveVoiceHandshake h=new LiveVoiceHandshake(); h.onLocalDescriptionSet(); h.onIceGatheringComplete(); HandshakeStep step=h.onAnswerReceived(LiveSessionAnswer.fromHttpResponse(200,"answer")); assertEquals(HandshakeStepKind.APPLY_ANSWER,step.getKind()); assertEquals("answer",step.getSdp()); assertEquals("",step.getReason()); }
 @Test public void rejectedAnswerFailsWithServerReason() { LiveVoiceHandshake h=new LiveVoiceHandshake(); h.onLocalDescriptionSet(); h.onIceGatheringComplete(); HandshakeStep step=h.onAnswerReceived(LiveSessionAnswer.failed("HTTP 401")); assertEquals(HandshakeStepKind.FAIL,step.getKind()); assertEquals("HTTP 401",step.getReason()); }
 @Test public void remoteDescriptionFailureHasFixedReason() { LiveVoiceHandshake h=new LiveVoiceHandshake(); HandshakeStep step=h.onRemoteDescriptionFailed(); assertEquals(HandshakeStepKind.FAIL,step.getKind()); assertEquals("remote_description_failed",step.getReason()); }
 @Test public void negotiationFailurePreservesReason() { LiveVoiceHandshake h=new LiveVoiceHandshake(); HandshakeStep step=h.onNegotiationFailed("negotiation_error"); assertEquals(HandshakeStepKind.FAIL,step.getKind()); assertEquals("negotiation_error",step.getReason()); }
 @Test public void dataChannelConnectsOnceAndLostConnectionDisconnects() { LiveVoiceHandshake h=new LiveVoiceHandshake(); h.onLocalDescriptionSet(); h.onIceGatheringComplete(); h.onAnswerReceived(LiveSessionAnswer.fromHttpResponse(200,"answer")); HandshakeStep connected=h.onDataChannelOpened(); assertEquals(HandshakeStepKind.CONNECTED,connected.getKind()); HandshakeStep disconnected=h.onConnectionLost("socket_closed"); assertEquals(HandshakeStepKind.DISCONNECTED,disconnected.getKind()); assertEquals("socket_closed",disconnected.getReason()); assertEquals(HandshakeStepKind.NONE,h.onDataChannelOpened().getKind()); }
 @Test public void lostConnectionBeforeConnectedFails() { LiveVoiceHandshake h=new LiveVoiceHandshake(); HandshakeStep step=h.onConnectionLost("lost"); assertEquals(HandshakeStepKind.FAIL,step.getKind()); assertEquals("lost",step.getReason()); }
 @Test public void terminalFailureIgnoresLaterEvents() { LiveVoiceHandshake h=new LiveVoiceHandshake(); h.onNegotiationFailed("bad"); assertEquals(HandshakeStepKind.NONE,h.onAnswerReceived(LiveSessionAnswer.fromHttpResponse(200,"s")).getKind()); assertEquals(HandshakeStepKind.NONE,h.onDataChannelOpened().getKind()); }
}
